const subject=$json.subject||'';const from=$json.from||'';const date=$json.date||'';
const body=String($json.textPlain||$json.text||$json.textHtml||'').slice(0,8000);
const sys="Ти фільтруєш новинні розсилки судноплавних ліній та IATA для експедитора Unitex (Одеса). Спочатку визнач, чи лист — це ЗАГАЛЬНА НОВИНА/інформаційна розсилка лінії (ставки, GRI/GRA, PSS, надбавки, сервіси, розклади, процедури/booking window, свята/затори, авіа-регуляції IATA, глобальні події), а НЕ оперативка по конкретному відправленню (booking confirmation, price overview по букінгу, BL draft, shipping instruction, invoice, номер букінгу/BL/контейнера). Поверни СТРОГО валідний JSON без markdown. Поля: is_news (bool), source (Hapag-Lloyd|CMA CGM|Maersk|IATA|Інша), summary (1-3 речення українською, суть новини), effective_date (YYYY-MM-DD|null), route (str|null), market_relevant (bool: true якщо ВИКОНУЄТЬСЯ ХОЧА Б ОДНЕ з: (1) один з кінців маршруту — Європа (Пн.Європа, Середземномор'я, Балтика, Чорне море, вкл. порти Польщі/Румунії/України) АБО Україна, незалежно від другого кінця (США, Канада, Азія, Далекий Схід, Китай, Індія, Близький Схід, Австралія, Нова Зеландія, Африка тощо — будь-який напрямок НА/З Європи чи України); (2) локальні тарифи/правила/процедури портів Польщі/Румунії/України; (3) ГЛОБАЛЬНА ситуація/подія, що впливає на світове судноплавство — Червоне море/Суец, Панамський канал, геополітика/війни, масштабні затори чи закриття портів, страйки, санкції, форс-мажор, погода глобального масштабу; (4) ГЛОБАЛЬНІ/загальнокомпанійні зміни лінії — нові альянси чи сервісна мережа, глобальна політика надбавок/умов, зміни загальних правил/процедур, цифрові платформи, масштабні програми blank sailings, зміни флоту/розкладів загалом. false ЛИШЕ якщо новина суто про КОНКРЕТНИЙ маршрут, що НЕ торкається Європи/України І НЕ є глобальною подією/зміною (напр. локальна GRI Азія→Пн.Америка, PSS Азія→Австралія, Азія→Африка, всередині Америк, локальне поза Європою)), url (посилання на повну новину з тіла листа — 'Learn more'/стаття/'View in browser'; вибери найрелевантніше саме до цієї новини; якщо немає — null), kb_relevant (bool: true лише якщо зміна правил/процедур АБО локальних тарифів для Польщі/Румунії/України), kb_section (Морський фрахт|Локальні витрати|Наземна доставка|null), kb_text (str|null). Рік за замовчуванням 2026. Не вигадуй посилань і дат.";
const payload={model:'claude-sonnet-4-6',max_tokens:1000,system:sys,messages:[{role:'user',content:'ВІД: '+from+'
ТЕМА: '+subject+'
ДАТА: '+date+'

ТІЛО:
'+body}]};
return [{json:{body:JSON.stringify(payload),_subject:subject,_from:from,_date:date}}];

let raw=($json.content&&$json.content[0]&&$json.content[0].text)||'';
const mm=raw.match(/\{[\s\S]*\}/);
let d;try{d=JSON.parse(mm?mm[0]:raw);}catch(e){return [];}
if(!d||d.is_news!==true||d.market_relevant!==true) return [];
const m=$('Запит до Claude').item.json;
const sd=$getWorkflowStaticData('global');
if(!Array.isArray(sd.buffer)) sd.buffer=[];
sd.buffer.push({source:d.source||'Інша',summary:d.summary||'',effective_date:d.effective_date||'',route:d.route||'',url:d.url||'',kb_relevant:!!d.kb_relevant,kb_section:d.kb_section||'',kb_text:d.kb_text||'',subject:m._subject||'',from:m._from||'',date:m._date||''});
return [{json:{buffered:sd.buffer.length}}];

const sd=$getWorkflowStaticData('global');
const buf=Array.isArray(sd.buffer)?sd.buffer:[];
if(buf.length===0) return [];
const order=['Hapag-Lloyd','CMA CGM','Maersk','IATA','Інша'];
const now=new Date().toLocaleString('uk-UA',{timeZone:'Europe/Kyiv',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
let t='\u{1F4EC} Дайджест новин ліній — '+now+'\n';
const by={};for(const it of buf){(by[it.source]=by[it.source]||[]).push(it);}
const keys=Object.keys(by).sort((a,b)=>{const ia=order.indexOf(a),ib=order.indexOf(b);return (ia<0?99:ia)-(ib<0?99:ib);});
for(const k of keys){t+='\n— '+k+' —\n';for(const it of by[k]){t+='\u2022 '+it.summary;if(it.effective_date)t+=' (дата дії: '+it.effective_date+')';if(it.route)t+=' ['+it.route+']';if(it.url)t+='\n  \u{1F517} Повна новина: '+it.url;t+='\n';}}
const kb=buf.filter(x=>x.kb_relevant&&x.kb_text);
if(kb.length){t+='\n\u{1F5C2} Запропоновано до Бази знань (Notion) — підтвердь, щоб додати:\n';for(const it of kb){t+='\n\u2022 Розділ: '+(it.kb_section||'')+'\n'+it.kb_text+'\nДжерело: '+it.from+' | '+it.subject+' | '+it.date+'\n';}}
const subject='\u{1F4EC} Дайджест новин ліній — '+now;
return [{json:{subject:subject,text:t,count:buf.length}}];
